<?php foreach($bookings as $booking): ?><tr><td><?= e($booking['guest_name']) ?><br><small><?= in_array($booking['status'],['confirmed','completed'],true)?e($booking['guest_phone']):e(__('Liên hệ sau xác nhận')) ?></small><?php if(in_array($booking['status'],['confirmed','completed'],true) && ($zaloUrl=\App\Services\ZaloLink::url($booking['guest_phone']))): ?><br><a class="btn btn-sm btn-soft zalo-link mt-1" href="<?= e($zaloUrl) ?>" target="_blank" rel="noopener noreferrer"><?= e(__('Liên hệ qua Zalo')) ?><span class="sr-only"> <?= e(__('với {name} (mở tab mới)', ['name' => $booking['guest_name']])) ?></span></a><?php endif; ?></td><td><a href="<?= e(url('/bookings/'.$booking['id'])) ?>"><?= e($booking['title']) ?> · #<?= (int)$booking['id'] ?></a><br><?= e(__('{count} khách', ['count' => (int)$booking['guest_count']])) ?></td><td><?= e($booking['check_in']) ?> → <?= e($booking['check_out']) ?></td><td><?= e(__('{amount}đ', ['amount' => number_format((float)$booking['total_amount'],0,',','.')])) ?><?php $payment=($payments??[])[(int)$booking['id']]??null; if($payment): ?><br><span class="status status-<?= e($payment['payment_state']) ?>"><?= e(__(\App\Models\BookingExtras::paymentLabel($payment['payment_state']))) ?></span><?php if($payment['can_mark_paid']): ?><form class="mt-1" method="post" action="<?= e(url('/host/bookings/'.$booking['id'].'/payment')) ?>"><?= csrf_field() ?><button class="btn btn-sm btn-soft" data-confirm="<?= e(__('Xác nhận đã thu {amount}đ của booking #{id}?', ['amount' => number_format((float)$payment['amount_due'],0,',','.'), 'id' => (int)$booking['id']])) ?>"><?= e(__('Đã thu tiền')) ?></button></form><?php endif; ?><?php endif; ?></td><td><span class="status status-<?= e($booking['status']) ?>"><?= e($booking['status']) ?></span><?php if(!empty($payment['is_instant_book'])): ?> <span class="instant-tag" title="<?= e(trim(str_replace('⚡','',__('⚡ Đặt ngay')))) ?>"><?= e(__('⚡ Đặt ngay')) ?></span><?php endif; ?><?php if($booking['status']==='pending'): ?><div class="action-row"><form method="post" action="<?= e(url('/host/bookings/'.$booking['id'].'/transition')) ?>"><?= csrf_field() ?><input type="hidden" name="status" value="confirmed"><button class="btn btn-sm btn-primary"><?= e(__('Chấp nhận')) ?></button></form><form method="post" action="<?= e(url('/host/bookings/'.$booking['id'].'/transition')) ?>"><?= csrf_field() ?><input type="hidden" name="status" value="rejected"><button class="btn btn-sm btn-outline-danger"><?= e(__('Từ chối')) ?></button></form></div><?php elseif($booking['status']==='confirmed'&&$booking['check_out']<=date('Y-m-d')): ?><form method="post" action="<?= e(url('/host/bookings/'.$booking['id'].'/transition')) ?>"><?= csrf_field() ?><input type="hidden" name="status" value="completed"><button class="btn btn-sm btn-primary"><?= e(__('Hoàn thành')) ?></button></form><?php endif; ?></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?></section>
